parameters.jsonBody:
={{ JSON.stringify({
  customer_name: $fromAI('customer_name', 'Nome completo do cliente', 'string'),
  customer_phone: String($fromAI('customer_phone', 'Telefone com DDD apenas digitos. Ex: 41999999999', 'string') || '').replace(/\D/g, ''),
  order_type: $fromAI('order_type', 'Delivery ou Retirada', 'string'),
  payment_method: $fromAI('payment_method', 'PIX, Cartao ou Dinheiro', 'string'),
  total_amount: Number($fromAI('total_amount', 'Valor total numerico em reais somando entrega se houver', 'number')) || 0,
  delivery_address: $fromAI('delivery_address', 'Endereco completo com rua e numero se Delivery ou null se Retirada', 'string') || null,
  delivery_zone: $fromAI('delivery_zone', 'Bairro em Sao Jose dos Pinhais se Delivery ou null se Retirada', 'string') || null,
  change_for: $fromAI('change_for', 'Troco para quanto se dinheiro ou null', 'string') || null,
  notes: $fromAI('notes', 'Observacoes do pedido ou null', 'string') || null,
  items: (function() {
    const raw = $fromAI('items', 'JSON string representando array de itens. Ex: [{"name":"Copo 500ml Acai","quantity":1,"priceCalculated":22.0,"notes":"Banana, Ninho, Morango"}]', 'string');
    try {
      return typeof raw === 'string' ? JSON.parse(raw) : (raw || []);
    } catch(e) {
      return [{ name: 'Acai', quantity: 1, priceCalculated: Number($fromAI('total_amount', '0', 'number')), notes: '' }];
    }
  })()
}) }}
